<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { onBeforeRouteLeave, onBeforeRouteUpdate, useRoute, useRouter } from 'vue-router'
import { ElMessage, ElMessageBox, vLoading } from 'element-plus'
import { useI18n } from 'vue-i18n'
import { useWorkspaceStore } from '@/stores/useWorkspaceStore'
import { ontologyApi } from '../api/ontologyApi'
import type { AxiomDescriptor, OntologyDocumentSyntax } from '../api/types'
import { useOntologyDraft } from './useOntologyDraft'
import ValidationPanel from './components/ValidationPanel.vue'
import PublishDialog from './components/PublishDialog.vue'
import OntologySourcePanel from './components/OntologySourcePanel.vue'
import OntologyModelWorkbench from './components/OntologyModelWorkbench.vue'
import OntologyLabelEditor from './components/OntologyLabelEditor.vue'
import './semantic.css'

const { t } = useI18n(); const route = useRoute(); const router = useRouter(); const workspace = useWorkspaceStore()
const ontologyId = () => String(route.params.id); const workspaceId = () => workspace.currentWorkspaceId ?? ''
const draft = useOntologyDraft(ontologyId, workspaceId)
const { document, axioms, name, description, id, dirty, busy, version, draftVersion, validationReport, saveError, canPublish, publicationPending } = draft
const editable = computed(() => workspace.can('manage:ontology') && !publicationPending.value)
const selectedAxiom = ref<AxiomDescriptor | null>(null); const newAxiom = ref(''); const tab = ref<'model' | 'editor' | 'axioms'>('model'); const publishOpen = ref(false)
const unsaved = computed(() => dirty.value)
async function confirmLeave() {
  if (publicationPending.value) { ElMessage.warning(t('semantic.pendingPublication')); return false }
  if (!unsaved.value) return true
  try { await ElMessageBox.confirm(t('semantic.leaveWarning'), t('semantic.unsaved'), { confirmButtonText: t('semantic.leave'), cancelButtonText: t('semantic.stay'), type: 'warning' }); return true } catch { return false }
}
const unregister = workspace.registerBeforeSwitch(confirmLeave); onBeforeRouteLeave(confirmLeave); onBeforeRouteUpdate(confirmLeave)
function unload(event: BeforeUnloadEvent) { if (unsaved.value || publicationPending.value) { event.preventDefault(); event.returnValue = '' } }
window.addEventListener('beforeunload', unload); onBeforeUnmount(() => { unregister(); window.removeEventListener('beforeunload', unload) })
async function removeAxiom(axiom: AxiomDescriptor) { if (!editable.value || dirty.value || busy.value) return; try { await ElMessageBox.confirm(t('semantic.deleteWarning', { key: axiom.axiomId }), t('semantic.delete'), { confirmButtonText: t('semantic.delete'), cancelButtonText: t('semantic.cancel'), type: 'warning' }); await draft.edit([{ kind: 'REMOVE', axiomId: axiom.axiomId }]); selectedAxiom.value = null } catch { /* cancelled */ } }
async function addAxiom() { if (!newAxiom.value.trim() || dirty.value || busy.value || !editable.value) return; if (await draft.edit([{ kind: 'ADD', functionalSyntax: newAxiom.value.trim() }])) newAxiom.value = '' }
async function exportRevision(syntax: OntologyDocumentSyntax) {
  if (!id.value || dirty.value || busy.value) return; try { const bytes = await ontologyApi.exportDraftDocument(workspaceId(), ontologyId(), draftVersion.value, syntax); const blob = new Blob([bytes], { type: syntax === 'RDF_XML' ? 'application/rdf+xml' : 'text/plain;charset=utf-8' }); const url = URL.createObjectURL(blob); const link = globalThis.document.createElement('a'); link.href = url; link.download = `ontology.${syntax === 'RDF_XML' ? 'rdf' : 'ofn'}`; link.click(); URL.revokeObjectURL(url) } catch (error) { ElMessage.error((error as Error).message) }
}
async function publish(note: string) { const result = await draft.publish(note); if (result) { publishOpen.value = false; await router.push({ name: 'OntologyVersions', params: { id: ontologyId() }, query: { revision: result.id } }) } }
async function discard() { try { await ElMessageBox.confirm(t('semantic.discardWarning'), t('semantic.discard'), { confirmButtonText: t('semantic.discard'), cancelButtonText: t('semantic.cancel'), type: 'warning' }); if (await draft.discard()) await router.push({ name: 'OntologyVersions', params: { id: ontologyId() } }) } catch { /* cancelled */ } }
function sourceChanged(nextVersion?: number) { if (nextVersion !== undefined) draftVersion.value = nextVersion; validationReport.value = null }
onMounted(draft.load)
</script>
<template>
  <section class="semantic-page">
    <header class="semantic-header"><div><h1>{{ name || t('semantic.draft') }}</h1><span class="semantic-muted">{{ t('semantic.draft') }} · v{{ version }} · {{ t('semantic.draftVersion') }} {{ draftVersion }} · {{ t(dirty ? 'semantic.unsaved' : 'semantic.saved') }}</span></div><div class="semantic-actions"><el-button @click="router.push({ name: 'OntologyList' })">{{ t('semantic.back') }}</el-button><el-button @click="router.push({ name: 'OntologyVersions', params: { id: ontologyId() } })">{{ t('semantic.history') }}</el-button><el-button :disabled="!id || dirty || busy" @click="exportRevision('FUNCTIONAL')">{{ t('semantic.exportFunctional', 'Export Functional') }}</el-button><el-button :disabled="!id || dirty || busy" @click="exportRevision('RDF_XML')">{{ t('semantic.exportRdfXml', 'Export RDF/XML') }}</el-button><template v-if="editable && id"><el-button :disabled="busy" @click="discard">{{ t('semantic.discard') }}</el-button><el-button type="primary" :disabled="!dirty || busy" @click="draft.save">{{ t('semantic.save') }}</el-button><el-button :disabled="dirty || busy" @click="draft.validate">{{ t('semantic.validate') }}</el-button></template><el-button v-if="workspace.can('publish:ontology') && id" type="primary" :disabled="!canPublish" @click="publishOpen = true">{{ t('semantic.publish') }}</el-button></div></header>
    <el-alert v-if="publicationPending" type="warning" :title="t('semantic.pendingPublication')" :closable="false" /><el-button v-if="publicationPending" :loading="busy" @click="publish('')">{{ t('semantic.recoverPublication') }}</el-button><el-alert v-if="!editable && !publicationPending" type="info" :title="t('semantic.readonly')" :closable="false" /><el-alert v-if="saveError" type="error" :title="saveError.code" :description="saveError.message || t(`semantic.errors.${saveError.code}`, t('semantic.requestFailed'))" :closable="false" />
    <div v-if="document" v-loading="busy" class="semantic-panel"><details class="model-metadata"><summary>{{ t('semantic.basicInfo', '基本信息') }} · {{ name }}</summary><el-form label-position="top" :disabled="!editable || busy"><div class="semantic-grid"><el-form-item :label="t('semantic.name')" required><el-input id="ontology-name" v-model="name" maxlength="128" /></el-form-item><el-form-item :label="t('semantic.description')"><el-input id="ontology-description" v-model="description" type="textarea" :rows="2" /></el-form-item></div></el-form></details><div class="semantic-toolbar"><el-radio-group v-model="tab"><el-radio-button label="model">{{ t('semantic.modelStructure', '本体结构') }}</el-radio-button><el-radio-button label="editor">{{ t('semantic.advancedDocument', '高级 OWL 文档') }}</el-radio-button><el-radio-button label="axioms">{{ t('semantic.axioms', 'Axioms') }} ({{ axioms.length }})</el-radio-button></el-radio-group><template v-if="tab !== 'model'"><el-tag>{{ document.syntax }}</el-tag><el-tag type="info">{{ document.modelSchema }}</el-tag></template></div><OntologyModelWorkbench v-if="tab === 'model'" :key="workspaceId() + ontologyId()" :axioms="axioms" :editable="editable && !!id" :disabled="busy || dirty" :apply="draft.edit" @advanced="tab = 'axioms'" /><el-alert v-if="tab === 'model' && dirty" type="info" :closable="false" :title="t('semantic.modelStale', '结构图基于已保存草稿；请先保存当前修改以更新图示。')" /><template v-if="tab === 'editor'"><el-form-item :label="t('semantic.documentText', 'OWL Functional Syntax document')"><el-input v-model="document.documentText" :disabled="!editable || busy" type="textarea" :rows="24" spellcheck="false" input-style="font-family: ui-monospace, monospace; line-height: 1.5" /></el-form-item><p class="semantic-muted">{{ document.documentText.length }} characters · {{ document.imports.length }} pinned imports · {{ document.policy.rules.length }} policy rules</p></template><template v-else-if="tab === 'axioms'"><div class="semantic-axiom-list"><el-table :data="axioms" :empty-text="t('semantic.emptyAxioms', 'No axioms')" @row-click="selectedAxiom = $event"><el-table-column prop="axiomType" :label="t('semantic.axiomType', 'Type')" width="190" /><el-table-column prop="rendering" :label="t('semantic.rendering', 'Functional rendering')" min-width="520" show-overflow-tooltip /><el-table-column :label="t('semantic.signature', 'Signature')" min-width="220"><template #default="{ row }">{{ row.signatureIris.join(', ') }}</template></el-table-column><el-table-column v-if="editable" width="100"><template #default="{ row }"><el-button link type="danger" @click.stop="removeAxiom(row)">{{ t('semantic.delete') }}</el-button></template></el-table-column></el-table><el-card v-if="selectedAxiom" class="semantic-axiom-detail"><code>{{ selectedAxiom.rendering }}</code><p>{{ selectedAxiom.annotations.length }} annotations · {{ selectedAxiom.signatureIris.length }} entities</p></el-card><OntologyLabelEditor v-if="editable" :axioms="axioms" :disabled="busy || dirty" @apply="draft.edit" /><el-form v-if="editable" label-position="top" @submit.prevent="addAxiom"><el-form-item :label="t('semantic.addAxiom', 'Add one Functional Syntax axiom')"><el-input v-model="newAxiom" type="textarea" :rows="4" spellcheck="false" /><el-button native-type="submit" type="primary" :disabled="!newAxiom.trim() || dirty || busy">{{ t('semantic.add') }}</el-button></el-form-item></el-form></div></template></div><ValidationPanel v-if="validationReport" :report="validationReport" :dirty="dirty" /><PublishDialog v-if="publishOpen" v-model="publishOpen" :busy="busy" :diff="null" @publish="publish" />
    <OntologySourcePanel v-if="document" :ontology-id="ontologyId()" :revision-id="id || undefined" @changed="sourceChanged" :draft-version="id ? draftVersion : undefined" :axioms="axioms" :can-manage="editable && !!id && !dirty && !busy" :can-review="workspace.can('publish:ontology')" />
  </section>
</template>

<style scoped>
.model-metadata{margin-bottom:16px;border-bottom:1px solid var(--mc-border)}.model-metadata summary{padding:8px 0 16px;cursor:pointer;font-size:13px;color:var(--mc-text-secondary)}.model-metadata .semantic-grid{grid-template-columns:1fr 1fr}@media(max-width:650px){.model-metadata .semantic-grid{grid-template-columns:1fr}}
</style>
